/// <reference types="react" />
import { ITooltipProps } from '../Tooltip';
import { TagColor } from '../Tag';
export type ColumnType = 'select' | 'alphanumeric' | 'numeric' | 'status' | 'custom' | 'header';
export type SortType = 'ascending' | 'descending' | 'none';
export type HeaderTooltipProps = Omit<ITooltipProps, 'triggerRef' | 'children'>;
export type ColumnDef = {
    /**
     * Index of the column
     */
    columnIndex: number;
    /**
     * Type of the column
     */
    type: ColumnType;
    /**
     * Display string on the column header
     */
    header: string;
    /**
     * Field name/key of the column
     */
    field: string;
    /**
     * To enable/disable sort
     */
    sort?: boolean;
    /**
     * Width of the column(in px)
     */
    width?: number;
    /**
     * If column needs to be fixed when scrolling of table is enabled(only first and last column for now)
     */
    fixedColumn?: boolean;
    /**
     * JSX element when the type is action
     */
    customElement?: (row?: object) => React.ReactNode;
    /**
     * Set status color when type is status
     */
    getStatusColor?: (row?: any) => TagColor;
    /**
     * To add a column divider style
     */
    showColumnDivider?: boolean;
    /**
     * To show header text,default will be true. if value is false opacity will be set to 0
     */
    showHeaderText?: boolean;
    /**
     *  Properties for header popover.
     */
    tooltipProps?: HeaderTooltipProps;
    /**
     * Text alignment for the header. If not specified, defaults to 'left' for most types and 'right' for numeric
     */
    alignment?: 'left' | 'right';
};
export type TableSortState = {
    attribute: string;
    order: SortType;
};
export type TableData = object & {
    id?: number | string;
};
